const M=RoomFlow;let s=M.initial(),modal=null,lastFocus=null,pendingAction=null,commandTimer=null,flow='controller';
const $=q=>document.querySelector(q),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={
 snow:'M12 3v18M4.2 7.5l15.6 9M4.2 16.5l15.6-9M9 5l3 3 3-3M9 19l3-3 3 3M4.5 11l4-1-1-4M19.5 13l-4 1 1 4M4.5 13l4 1-1 4M19.5 11l-4-1 1-4',
 power:'M12 3v9M6.3 5.7a8 8 0 1 0 11.4 0',
 bulb:'M9 18h6M10 21h4M8.4 14.5a6 6 0 1 1 7.2 0c-1 .8-1.6 1.5-1.6 3.5h-4c0-2-.6-2.7-1.6-3.5Z',
 refresh:'M20 7v5h-5M4 17v-5h5M6.1 6.1A8 8 0 0 1 19 8M5 16a8 8 0 0 0 12.9 1.9',
 more:'M12 5h.01M12 12h.01M12 19h.01',
 down:'m8 10 4 4 4-4',right:'m9 6 6 6-6 6',back:'m15 6-6 6 6 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',
 thermo:'M10 14.8V5a2 2 0 0 1 4 0v9.8a4 4 0 1 1-4 0ZM12 10v7',
 chart:'M4 4v16h16M8 15v-4M12 15V7M16 15v-6',
 fan:'M12 10c-3-6 3-9 5-5 1 3-2 5-5 5Zm2 2c6-3 9 3 5 5-3 1-5-2-5-5Zm-2 2c3 6-3 9-5 5-1-3 2-5 5-5Zm-2-2c-6 3-9-3-5-5 3-1 5 2 5 5ZM10 12a2 2 0 1 0 4 0 2 2 0 0 0-4 0',
 sliders:'M4 6h5M13 6h7M4 12h9M17 12h3M4 18h2M10 18h10M9 3v6M13 9v6M6 15v6',
 home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',external:'M14 3h7v7M21 3l-11 11M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5',
 settings:'M9 4l1-2h4l1 2 3 2 2 1-1 4v2l1 4-2 1-3 2-1 2h-4l-1-2-3-2-2-1 1-4v-2L4 7l2-1ZM9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',
 wifi:'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0M12 20h.01',signal:'M4 20v-3M9 20v-7M14 20V9M19 20V4',battery:'M4 7h14v12H4ZM18 11h2v4M7 10h8v6H7Z',
 breeze:'M3 8h11a3 3 0 1 0-3-3M3 12h15a3 3 0 1 1-3 3M3 16h5a3 3 0 1 1-3 3',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z'};
const icon=name=>`<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${iconPaths[name]||iconPaths.spark}"/></svg>`;
const btn=(text,action,cls='',disabled=false,extra='')=>`<button class="${cls}" data-act="${action}" ${disabled?'disabled':''} ${extra}>${({'‹':icon('back'),'⌄':icon('down'),'↻':icon('refresh'),'⋮':icon('more'),'×':icon('close'),'−':icon('minus'),'+':icon('plus')})[text]||text}</button>`;
const notes={controller:'Temperature and mode edits are drafts. Set or Apply sends a request; reported values change only after matching readback.',readings:'Readings are snapshots. Energy loads on request; today may be incomplete. Each export uses Android’s file picker in the native app.',signin:'First use: sign in → discover ACs → choose one → load capabilities and status. Use the prefilled sample account here.',devices:'Switching ACs clears local drafts after confirmation. Widgets follow the selected AC; data is never carried between devices.',widgets:'Manual refresh only. Widget state and actions follow the selected AC. The Display action is proposed; target taps open the app.',settings:'Account, diagnostics, widget setup and local appearance live away from everyday controls.'};
function journey(id){clearTimeout(commandTimer);s=M.initial();flow=id;modal=null;if(id==='signin'){s.signed=false;s.device=null;s.screen='signin';}else if(id==='devices'){s.device=null;s.screen='devices';}else s.screen=id;render();}
$('#journeys').innerHTML=[['controller','01|Controller'],['readings','02|Readings'],['signin','03|Sign in'],['devices','04|Choose an AC'],['widgets','05|Widgets'],['settings','06|Settings']].map(([id,t])=>btn('<span class="journey-number">'+t.split('|')[0]+'</span>'+t.split('|')[1],'journey:'+id)).join('');
$('#scenarios').innerHTML=[['off','AC off'],['dry','Dry mode'],['fan','Fan-only'],['cleaning','Cleaning active'],['missing','Missing readings'],['unknown-display','Unknown display state'],['no-capabilities','Capabilities unavailable'],['device-offline','AC offline'],['empty','No devices'],['one-device','One AC discovered'],['energy-empty','No energy entries'],['no-pin','Launcher cannot pin'],['large-text','Large text'],['widget-signedout','Widget signed out'],['widget-no-device','Widget no AC'],['dark','Dark appearance']].map(([id,t])=>btn(t,'scenario:'+id)).join('');
function header(title,back=false){return `<header class="topbar">${back?btn('‹','back','plain icon',false,'aria-label="Back"'):''}<h2>${title}${s.screen==='controller'?'<span class="room-subtitle">Panasonic AC</span>':''}</h2>${s.screen==='controller'?btn('⌄','devices','plain room-picker',s.busy,'aria-label="Choose air conditioner"'):''}${['controller','readings'].includes(s.screen)?btn('↻','refresh','plain icon',s.busy,'aria-label="Refresh status"')+btn('⋮','menu','plain icon',false,'aria-label="More options"'):''}</header>`;}
function nav(){return `<nav class="bottomnav" aria-label="Main">${btn('<span class="nav-icon">'+icon('thermo')+'</span><span>Controller</span>','nav:controller',s.screen==='controller'?'selected':'')}${btn('<span class="nav-icon">'+icon('chart')+'</span><span>Readings</span>','nav:readings',s.screen==='readings'?'selected':'')}</nav>`;}
function notice(){return s.notice?`<div class="notice ${s.severity==='error'?'error':''}" role="status">${s.busy?'<span class="pending-dot"></span>':''}<span>${esc(s.notice)}</span>${!s.busy&&s.severity==='error'?`<div class="mt">${s.screen==='signin'?'':btn(s.screen==='devices'?'Find my ACs':'Refresh status',s.screen==='devices'?'discover':'refresh','plain')}${btn('Dismiss','dismiss','plain')}</div>`:''}</div>`:'';}
function unavailable(){return !s.power?'Power on to change these settings.':!s.capabilities?'Refresh capabilities to load supported controls.':!s.deviceOnline?'AC offline. Refresh when it reconnects.':s.draftMode!==s.mode?'Apply your selected mode before changing temperature or fan.':s.cleaning?'Cleaning is active. Temperature and fan controls are unavailable.':'';}
function toggle(title,key,on,enabled){return `<section class="card quick ${on?'on':''}"><div class="row between"><span class="quick-icon">${icon(key==='power'?'power':'bulb')}</span><div class="switch-wrap">${btn('','toggle:'+key,'switch',!enabled,`role="switch" aria-label="${title}" aria-checked="${on===true}" ${on===null?'aria-describedby="unknown-display"':''}`)}</div></div><h3>${title}</h3><span class="tiny" ${on===null?'id="unknown-display"':''}>${on===null?'Not reported':on?'On':'Off'}</span></section>`;}
function controller(){const tempAllowed=M.allowed(s,'temperature'),draft=s.draftTarget!==s.target,modeDraft=s.draftMode!==s.mode;return header(esc(s.device))+`<div class="content">${notice()}<div class="row between statusline"><span><i class="online-dot ${s.deviceOnline?'':'offline'}"></i>${s.deviceOnline?'Connected':'AC offline'}</span><span>Updated ${esc(s.updated)}</span></div><section class="hero"><div class="row between wrap"><span class="mode-label">${icon(s.mode==='Fan'?'breeze':'snow')}${s.power?s.mode:'Power off'}</span><span class="room-label">Room ${s.missing?'unavailable':s.room+'°C'}</span></div>${s.draftMode==='Fan'?`<div class="empty"><div class="symbol">${icon('breeze')}</div><h3>Just a breeze.</h3><p class="tiny muted">Fan-only has no target temperature.</p></div>`:`<p class="value-label">${draft?'Selected target':'Target temperature'}</p><div class="row between temp-line">${btn('−','temp:-1','step',!tempAllowed||s.draftTarget<=16,'aria-label="Decrease target temperature"')}<div><span class="temp">${s.draftTarget}</span><span class="unit">°C</span></div>${btn('+','temp:1','step',!tempAllowed||s.draftTarget>=30,'aria-label="Increase target temperature"')}</div><p class="applied muted">${draft?'AC reports '+s.target+'°C':'Reported by your AC'}</p>${btn('Set '+s.draftTarget+'°C','set-temp','primary commit',!tempAllowed||!draft)}${draft?btn('Reset selection','reset-temp','plain reset-draft'):''}`}</section><div class="twocol">${toggle('AC power','power',s.power,M.allowed(s,'power'))}${toggle('AC display','display',s.display,M.allowed(s,'display'))}</div>${s.display===null?'<p class="tiny muted">Display state unavailable. Refresh before toggling.</p>':''}<section class="card mode-card"><div class="row between"><h3>Mode</h3><span class="tiny muted">Active: ${s.mode}</span></div><div class="modegroup" role="group" aria-label="Operating mode">${M.modes.map(m=>btn((s.draftMode===m?icon('check'):'')+m,'mode:'+m,s.draftMode===m?'selected':'',!M.allowed(s,'mode'),`aria-pressed="${s.draftMode===m}"`)).join('')}</div>${modeDraft?`<div class="row between mt"><span class="tiny">Selected: ${s.draftMode}</span>${btn('Apply '+s.draftMode,'apply-mode','primary')}</div>${btn('Cancel selection','reset-mode','plain')}`:''}</section>${unavailable()?`<p class="tiny muted">${unavailable()}</p>`:''}${btn(`${icon('fan')}<span>Fan speed<small>${s.mode==='Dry'?'Managed by Dry mode':s.fan}</small></span><span class="tail">${icon('right')}</span>`,'fan','listrow',!M.allowed(s,'fan'))}${btn(`${icon('sliders')}<span>More controls<small>Eco · Powerful · Capacity</small></span><span class="tail">${icon('right')}</span>`,'more','listrow',!s.capabilities)}${!s.capabilities?btn('Refresh capabilities','capabilities','tonal',s.busy):''}${s.cleaning?'<p class="tiny muted">Cleaning status is reported only; this app does not start or stop cleaning.</p>':''}</div>`+nav();}
const row=(name,value)=>`<div class="data"><span>${name}</span><strong>${value}</strong></div>`;
function readings(){return header('Readings')+`<div class="content">${notice()}<p class="tiny muted">Updated ${s.updated} · Manual refresh</p><section class="card"><h3>Room conditions</h3><span class="stat">${s.missing?'—':s.room+'°C'}</span><p class="tiny muted">${s.missing?'Room temperature not reported':'Room temperature · last reported'}</p>${row('Fan setting',s.fan)}${row('AC status',s.deviceOnline?'Online':'Offline')}${row('Power',s.power?'On':'Off')}${row('Display',s.display===null?'Not reported':s.display?'On':'Off')}<p class="tiny muted">Measured fan RPM, humidity and compressor frequency are unavailable for this AC.</p></section><section class="card"><h3>Energy</h3><p class="tiny muted">Daily reported kWh, loaded on request. Today can be incomplete.</p>${s.energy?`<table class="energy-table"><thead><tr><th>Date</th><th>Energy</th></tr></thead><tbody><tr><td>Today · partial</td><td>1.26 kWh</td></tr><tr><td>Yesterday</td><td>3.48 kWh</td></tr><tr><td>17 Oct</td><td>2.10 kWh</td></tr><tr><td>16 Oct</td><td>2.32 kWh</td></tr><tr><td>15 Oct</td><td>2.58 kWh</td></tr><tr><td>14 Oct</td><td>1.88 kWh</td></tr><tr><td>13 Oct</td><td>2.40 kWh</td></tr></tbody></table><p class="tiny muted">16.02 kWh · 7 reported entries<br>Sample values for design review</p>`:s.energyEmpty?'<p>No energy entries returned for this period.</p>':'<p class="muted">Energy hasn’t been loaded yet.</p>'}${btn(s.energy?'Reload recent energy':'Load recent energy','energy','tonal',s.busy)}${s.energy?btn('Export energy CSV','export:energy','plain',s.busy):''}</section><section class="card"><h3>Saved readings</h3><p><strong>${s.snapshots}</strong> snapshots on this phone</p><p class="tiny muted">Saved on refresh and command readback, up to 5,000. No continuous recording.</p>${btn('Export readings CSV','export:readings','tonal',s.busy||s.snapshots===0)}</section>${btn(`Device details & diagnostics <span class="tail">${icon('right')}</span>`,'details','listrow')}</div>`+nav();}
function signin(){return header('openMirAIe')+`<div class="content"><div class="empty"><div class="symbol">${icon('spark')}</div><h3>Your room. Your way.</h3><p class="muted">Sign in with your Panasonic MirAIe account.</p></div>${notice()}<div class="notice">Prototype only. Use the sample account below. Don’t enter real credentials.</div><form class="form" id="login-form"><label for="identity">Mobile number or email</label><input id="identity" value="demo@example.invalid" autocomplete="off" aria-describedby="login-help"><label for="password">Password</label><div class="password"><input id="password" type="password" value="sample-password" autocomplete="off">${btn('Show','show-password','plain',false,'aria-label="Show password"')}</div><p class="tiny muted" id="login-help">No registration or password reset in this alternative app.</p><button class="primary mt" type="submit" ${s.busy?'disabled':''}>${s.busy?'Signing in…':'Sign in'}</button></form>${btn('Forgot password?','forgot','plain')}${s.expired?'<p class="tiny muted">Your session expired. Sign in again to reconnect the selected AC.</p>':''}</div>`;}
function devices(){return header('Choose an AC',!!s.device)+`<div class="content">${notice()}${s.devices.length?`<p class="muted tiny">Select the AC used by the controller and widgets.</p>${s.devices.map((d,i)=>btn(`${icon('home')}<span>${esc(d)}<small>${i?'Upstairs':'Main room'}${s.device===d?' · Selected':''}</small></span><span class="tail">${s.device===d?'✓':'›'}</span>`,'device:'+d,'listrow',s.busy)).join('')}`:`<div class="empty"><div class="symbol">${icon('home')}</div><h3>No supported ACs found</h3><p class="muted">Check your MirAIe account and device setup in Panasonic’s app, then try again.</p></div>`}${btn('Find my ACs','discover','tonal',s.busy)}${btn('Sign out','signout','plain',s.busy)}</div>`;}
function settings(){return header('Settings',true)+`<div class="content">${notice()}<section class="card"><h3>Selected AC</h3><p>${esc(s.device||'None selected')}</p>${btn('Choose another AC','devices','tonal',s.busy)}</section>${btn(`Add home-screen widget <span class="tail">${icon('right')}</span>`,'pin','listrow')}${btn(`Device details & diagnostics <span class="tail">${icon('right')}</span>`,'details','listrow')}${btn('Refresh capabilities <span class="tail">↻</span>','capabilities','listrow',s.busy)}<section class="card"><h3>Appearance</h3><p class="tiny muted">Native app follows the Android system theme. Preview both here.</p>${btn(s.dark?'Preview light':'Preview dark','appearance','tonal')}</section><section class="card"><h3>Account</h3><p class="tiny muted">Signed in · credentials stay on this phone</p>${btn('Sign out','signout','danger',s.busy)}<p class="tiny muted">Signing out removes the saved session. Local snapshots remain in app storage.</p></section><p class="tiny muted">openMirAIe · Independent MirAIe client<br>Controls depend on the capabilities reported by your AC.</p></div>`;}
function widgets(){const empty=!s.signed||!s.device,wide=s.widgetSize!=='compact';return `<div class="content home"><div class="homeclock">10:24</div><p class="tiny">Monday, 19 October</p><div class="row">${btn('Compact','widget-size:compact',wide?'':'tonal')}${btn('Wide','widget-size:wide',wide?'tonal':'')}</div><section class="widget ${wide?'wide':'compact'}" aria-label="openMirAIe widget">${empty?`<h3>openMirAIe</h3>${btn(s.signed?'Choose AC':'Sign in','widget-open','tonal')}`:`<div class="whead">${btn(esc(s.device)+icon('external'),'widget-open','plain',false,'aria-label="Open selected AC controller"')}<span>${s.busy?'Updating…':s.updated}</span></div><div class="${wide?'wbody':'wmid'}"><div><span class="chip yellow">${s.power?'On':'Off'} · ${s.mode}</span><div class="wtemp">${s.mode==='Fan'?'Fan':s.target+'°C'}</div>${wide?`<span class="tiny">Room: ${s.missing?'unavailable':s.room+'°C'}</span>`:''}</div><div class="${wide?'stack':'hidden'}">${wide?btn(s.power?'Turn off':'Turn on','toggle:power','',!M.allowed(s,'power')):''}</div></div><div class="row ${wide?'mt':'wactions'}">${!wide?btn(s.power?'Off':'On','toggle:power','',!M.allowed(s,'power')):''}${wide?btn('Display '+(s.display===null?'?':s.display?'On':'Off'),'toggle:display','tonal grow',!M.allowed(s,'display')):''}${btn('↻','refresh','refresh',s.busy,'aria-label="Refresh widget"')}</div>`}</section>${s.notice?`<div class="notice ${s.severity==='error'?'error':''}" role="status">${esc(s.notice)}${s.severity==='error'?btn('Open app','widget-open','plain'):''}</div>`:''}<p class="tiny muted">${wide?'Display action is proposed. ':''}Manual refresh · Last-known reported state.</p><div class="launcher">${btn(icon('spark'),'widget-open','',false,'aria-label="Open openMirAIe"')}${btn(icon('settings'),'nav:settings','',false,'aria-label="Open settings"')}</div></div>`;}
function render(){document.documentElement.classList.toggle('dark',s.dark);$('#phone').classList.toggle('large',!!s.large);$('#app').innerHTML=({controller,readings,signin,devices,settings,widgets}[s.screen]||controller)();$('#explanation').textContent=notes[flow]||notes.controller;document.querySelectorAll('#journeys button').forEach(b=>b.classList.toggle('active',b.dataset.act==='journey:'+flow));renderModal();}
function open(type,data={}){lastFocus=document.activeElement;modal={type,...data};renderModal();queueMicrotask(()=>$('#modal-root button:not(:disabled)')?.focus());}
function close(){modal=null;$('#modal-root').innerHTML='';lastFocus?.isConnected&&lastFocus.focus();}
function renderModal(){if(!modal){$('#modal-root').innerHTML='';$('#phone').inert=false;return;}$('#phone').inert=true;let title='',body='';const action=(label,a,cls='primary',disabled=false)=>btn(label,a,cls,disabled);
 if(modal.type==='fan'){title='Fan speed';body=`<p class="tiny muted">A setting, not measured RPM. Choose, then tap Set fan.</p>${M.fans.map(f=>action((modal.value===f?'✓ ':'')+f,'fan-choice:'+f,'choice '+(modal.value===f?'selected':''))).join('')}<div class="actions">${action('Cancel','close','plain')}${action('Set fan','set-fan','primary',modal.value===s.fan)}</div>`;}
 if(modal.type==='more'){title='More controls';body=`<p class="tiny muted">Reported settings. Changes are verified before updating.</p><div class="sub"><div class="row between"><strong>Eco · ${s.eco?'On':'Off'}</strong>${action(s.eco?'Turn off':'Turn on','eco','tonal',!M.allowed(s,'eco'))}</div><p class="tiny muted">${s.mode!=='Cool'?'Available in Cool mode.':'Enabling Eco also sets the target to 26°C.'}</p></div><div class="sub"><div class="row between"><strong>Powerful · ${s.powerful?'On':'Off'}</strong>${action(s.powerful?'Turn off':'Turn on','powerful','tonal',!M.allowed(s,'powerful'))}</div><p class="tiny muted">Cool mode only. Turning on disables fixed capacity.</p></div><div class="sub"><strong>Capacity · ${s.capacity?s.capacity+'%':'Normal'}</strong><p class="tiny muted">Fixed capacity turns Powerful off. This is a setting, not measured power.</p><div class="capacity">${[0,40,50,60,70,80,90,100,110].map(n=>action(n?n+'%':'Normal','capacity-choice:'+n,modal.value===n?'selected':'',!M.allowed(s,'capacity'))).join('')}</div>${action('Set capacity','set-capacity','primary mt',!M.allowed(s,'capacity')||modal.value===s.capacity)}</div>${unavailable()?'<p class="tiny muted">'+unavailable()+'</p>':''}`;}
 if(modal.type==='confirm'){title=modal.title;body=`<p>${modal.text}</p><div class="actions">${action('Cancel','close','plain')}${action(modal.label||'Continue','confirm')}</div>`;}
 if(modal.type==='menu'){title='More options';body=[['Settings','nav:settings'],['Choose another AC','devices'],['Add home-screen widget','pin'],['Device details','details']].map(([t,a])=>action(t,a,'choice')).join('');}
 if(modal.type==='details'){title='Device details';body=`<p class="tiny muted">Synthetic sample · updated ${s.updated}</p>${row('Model','CS-CU-NU18BKY5WX')}${row('Wi-Fi signal',s.missing?'Not reported':'−56 dBm (reported)')}${row('Warnings',s.missing?'Not reported':'None reported')}${row('Errors',s.missing?'Not reported':'None reported')}<p class="tiny muted">Other fields appear only when reported. Unavailable sensors stay unavailable.</p>${action('All reported fields','raw','choice')}${action('Collect diagnostic snapshot','inspect','choice',s.busy)}${action('Refresh capabilities','capabilities','choice',s.busy)}`;}
 if(modal.type==='raw'){title='Reported fields';body=`<p class="tiny muted">Advanced · sample data only. The native app shows the selected AC’s reported fields.</p><pre>${esc(JSON.stringify({ps:s.power?'on':'off',acmd:s.mode.toLowerCase(),actmp:s.target,acfs:s.fan.toLowerCase(),acdc:s.display===null?null:s.display?'on':'off',rmtmp:s.missing?null:s.room,onlineStatus:s.deviceOnline,rssi:-56},null,2))}</pre>${action('Back to details','details','plain')}`;}
 if(modal.type==='export'){title='Save '+(modal.kind==='energy'?'energy':'readings')+' CSV';body=`<div class="notice">Android system file picker handoff</div><p>Choose a folder and filename in the native app. This prototype can download a sample CSV.</p><label for="filename">Filename</label><p id="filename" class="tiny">openmiraie-${modal.kind}-sample.csv</p><div class="actions">${action('Cancel','close','plain')}${action('Download sample CSV','download:'+modal.kind)}</div><p class="tiny muted">Review an OS write error:</p>${action('Simulate save failure','save-failed','plain')}`;}
 if(modal.type==='pin'){title='Add a widget';body=`<p>Choose a size, then confirm placement in your Android launcher.</p><div class="stack">${action('Compact · target, power, refresh','pin-size:compact','tonal')}${action('Wide · adds room and display','pin-size:wide','tonal')}</div><p class="tiny muted">Display control is proposed. Cell sizes vary by launcher; layout adapts to available space.</p>`;}
 if(modal.type==='pin-confirm'){title='Add openMirAIe widget?';body=`<div class="notice">Android launcher confirmation</div><p>${modal.value==='compact'?'Compact':'Wide'} widget · selected AC: ${esc(s.device||'none')}</p><div class="actions">${action('Cancel','close','plain')}${action('Add to home screen','pin-done')}</div>`;}
 if(modal.type==='info'){title=modal.title;body=`<p>${modal.text}</p>${action('Got it','close','primary mt')}`;}
 $('#modal-root').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle"></div><div class="sheethead"><h2 id="sheet-title">${title}</h2>${btn('×','close','plain icon',false,'aria-label="Close dialog"')}</div>${body}</section>`;}
function confirm(title,text,fn,label='Continue'){pendingAction=fn;open('confirm',{title,text,label});}
function guardDraft(fn){if(M.dirty(s))confirm('Discard changes?','Your selected temperature or mode hasn’t been sent. Discard it to continue.',()=>{M.resetDraft(s);fn();},'Discard & continue');else fn();}
function navigate(screen){close();if(!s.signed&&screen!=='widgets')screen='signin';else if(!s.device&&!['signin','devices','widgets'].includes(screen))screen='devices';s.screen=screen;render();}
function outcome(){let v=$('#outcome').value;$('#outcome').value='success';return v;}
function request(kind,value){if(s.busy)return;close();const result=outcome(),before={target:s.target,mode:s.mode},requested=({power:'Power '+(value?'On':'Off'),display:'Display '+(value?'On':'Off'),temperature:'Target '+value+'°C',mode:'Mode '+value,fan:'Fan '+value,eco:'Eco '+(value?'On (target 26°C)':'Off'),powerful:'Powerful '+(value?'On':'Off'),capacity:'Capacity '+(value?value+'%':'Normal')})[kind];s.busy=true;s.notice=kind==='refresh'?'Refreshing reported state…':kind==='energy'?'Loading daily energy…':kind==='login'?'Signing in…':kind==='discover'?'Finding your ACs…':kind==='capabilities'?'Loading supported controls…':kind==='inspect'?'Collecting device data…':'Sending change…';s.severity='info';render();commandTimer=setTimeout(()=>{if(kind==='login'&&result==='unconfirmed'){s.busy=false;s.notice='Sign-in could not be verified. Try again.';s.severity='error';render();return;}if(!['login','discover','energy','capabilities','inspect','refresh'].includes(kind)&&result==='success'){s.notice='Checking reported state…';render();commandTimer=setTimeout(()=>finish(),800);}else finish();},700);
 function finish(){s.busy=false;if(result==='expired'&&kind!=='login'){s.expired=true;s.signed=false;s.screen='signin';s.notice='Your session expired. Sign in again.';s.severity='error';M.resetDraft(s);render();return;}if(result==='offline'||result==='failure'||result==='expired'){s.notice=result==='offline'?'No internet connection. Last-known values are shown.':kind==='login'?'Couldn’t sign in. Check your details and try again.':'The request failed. Last-known values are shown. Refresh to check your AC.';s.severity='error';render();return;}if(result==='unconfirmed'){s.notice=['refresh','energy','discover','capabilities','inspect'].includes(kind)?'Couldn’t complete this read. Try Refresh again.':(requested+' sent; the AC hasn’t reported it yet. Refresh to check. It may still take effect.');s.severity='error';render();return;}s.severity='info';if(kind==='login'){s.signed=true;s.expired=false;s.notice='Signed in. Finding your ACs…';s.screen='devices';render();request('discover');return;}if(kind==='discover'){s.notice=s.devices.length?'Choose your AC.':'No supported ACs found.';if(s.devices.length===1){s.device=s.devices[0];s.screen='controller';s.notice='AC selected. Loading status…';render();request('refresh');return;}}else if(kind==='energy'){s.energy=!s.energyEmpty;s.notice=s.energy?'Energy loaded. Today may be incomplete.':'No energy entries returned.';}else if(kind==='capabilities'){s.capabilities=true;s.notice='Supported controls refreshed.';}else if(kind==='inspect'){s.notice='Diagnostic snapshot collected in app-private storage. Sample only here.';}else{M.apply(s,kind,value);s.notice=kind==='refresh'?'Reported state refreshed. One reading snapshot saved.':'AC reports the updated setting.';if(before.mode!==s.mode&&s.mode==='Dry')s.notice+=' Dry manages fan speed automatically.';if(before.mode!==s.mode&&s.mode==='Fan')s.notice+=' Fan-only has no target temperature.';}render();}
}
function scenario(id){close();if(id==='dark'){s.dark=!s.dark;render();return;}if(id==='large-text'){s.large=!s.large;render();return;}if(id==='empty'){s.devices=[];s.device=null;s.screen='devices';}if(id==='one-device'){s.devices=['Bedroom'];s.device=null;s.screen='devices';}if(id==='energy-empty'){s.energy=false;s.energyEmpty=true;s.screen='readings';}if(id==='no-pin'){s.noPin=true;open('info',{title:'Add from your launcher',text:'This launcher cannot add widgets from the app. Long-press the home screen, choose Widgets, then openMirAIe.'});return;}if(id==='widget-signedout'){s.signed=false;s.screen='widgets';render();return;}if(id==='widget-no-device'){s.device=null;s.screen='widgets';render();return;}if(id==='off')s.power=false;if(id==='dry')s.mode='Dry';if(id==='fan')s.mode='Fan';if(id==='cleaning')s.cleaning=true;if(id==='missing')s.missing=true;if(id==='unknown-display')s.display=null;if(id==='no-capabilities')s.capabilities=false;if(id==='device-offline')s.deviceOnline=false;M.resetDraft(s);if(!['empty','one-device','energy-empty'].includes(id))s.screen='controller';s.notice='Review scenario: '+id.replaceAll('-',' ');render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const [a,...rest]=el.dataset.act.split(':'),v=rest.join(':');if(a==='journey'){journey(v);return;}if(a==='scenario'){scenario(v);return;}if(a==='close'){close();return;}if(a==='confirm'){const fn=pendingAction;pendingAction=null;close();fn?.();return;}if(a==='nav'){navigate(v);return;}if(a==='system-back'){if(modal)close();else if(['settings','devices'].includes(s.screen)&&s.device)navigate('controller');else open('info',{title:'App moves to background',text:'Android Back leaves the app here. Unsent changes are never sent automatically. Return to the app to continue.'});return;}if(a==='back'){navigate(s.device?'controller':'devices');return;}if(a==='menu'){open('menu');return;}if(a==='dismiss'){s.notice='';render();return;}if(a==='refresh'){request('refresh');return;}if(a==='devices'){guardDraft(()=>navigate('devices'));return;}if(a==='device'){guardDraft(()=>{s.device=v;s.screen='controller';s.energy=false;s.energyEmpty=false;s.snapshots=v==='Bedroom'?18:4;s.mode='Cool';s.power=true;s.display=true;s.fan='Auto';s.eco=false;s.powerful=false;s.capacity=0;s.cleaning=false;s.target=v==='Bedroom'?23:25;s.room=v==='Bedroom'?24.18:26.04;M.resetDraft(s);render();request('refresh');});return;}if(a==='discover'){request('discover');return;}if(a==='temp'){if(!M.allowed(s,'temperature'))return;s.draftTarget=Math.max(16,Math.min(30,s.draftTarget+Number(v)));render();return;}if(a==='set-temp'){request('temperature',s.draftTarget);return;}if(a==='reset-temp'){s.draftTarget=s.target;render();return;}if(a==='mode'){const change=()=>{s.draftMode=v;s.draftTarget=s.target;render();};if(s.draftTarget!==s.target)confirm('Discard temperature draft?','Changing mode resets your unsent temperature selection.',change,'Discard & select mode');else change();return;}if(a==='apply-mode'){request('mode',s.draftMode);return;}if(a==='reset-mode'){M.resetDraft(s);render();return;}if(a==='toggle'){guardDraft(()=>request(v,!s[v]));return;}if(a==='fan'){open('fan',{value:s.fan});return;}if(a==='fan-choice'){modal.value=v;renderModal();return;}if(a==='set-fan'){request('fan',modal.value);return;}if(a==='more'){open('more',{value:s.capacity});return;}if(a==='capacity-choice'){modal.value=Number(v);renderModal();return;}if(a==='set-capacity'){let n=modal.value;guardDraft(()=>s.powerful&&n!==0?confirm('Turn Powerful off?',`Setting capacity to ${n}% turns Powerful off.`,()=>request('capacity',n),'Set capacity'):request('capacity',n));return;}if(a==='eco'){guardDraft(()=>!s.eco?confirm('Enable Eco?',`Eco will set the target to 26°C. Your AC currently reports ${s.target}°C.`,()=>request('eco',true),'Enable Eco'):request('eco',false));return;}if(a==='powerful'){guardDraft(()=>!s.powerful&&s.capacity!==0?confirm('Enable Powerful?',`This resets fixed capacity (${s.capacity}%) to Normal.`,()=>request('powerful',true),'Enable Powerful'):request('powerful',!s.powerful));return;}if(a==='energy'){request('energy');return;}if(a==='export'){open('export',{kind:v});return;}if(a==='save-failed'){open('info',{title:'Couldn’t save the CSV',text:'The selected location could not be written. Your readings are safe. Close this message and choose Export again to select another location.'});return;}if(a==='download'){download(v);return;}if(a==='details'){open('details');return;}if(a==='raw'){open('raw');return;}if(a==='inspect'||a==='capabilities'){request(a);return;}if(a==='appearance'){s.dark=!s.dark;render();return;}if(a==='pin'){if(s.noPin)scenario('no-pin');else open('pin');return;}if(a==='pin-size'){open('pin-confirm',{value:v});return;}if(a==='pin-done'){s.widgetSize=modal.value;close();s.screen='widgets';s.notice='Widget added · simulated Android launcher';render();return;}if(a==='widget-size'){s.widgetSize=v;render();return;}if(a==='widget-open'){navigate(!s.signed?'signin':!s.device?'devices':'controller');return;}if(a==='show-password'){let p=$('#password');p.type=p.type==='password'?'text':'password';el.textContent=p.type==='password'?'Show':'Hide';el.setAttribute('aria-label',el.textContent+' password');return;}if(a==='forgot'){open('info',{title:'Reset your password',text:'Use Panasonic MirAIe’s password reset flow, then return here to sign in. This app doesn’t create accounts or reset passwords.'});return;}if(a==='signout'){guardDraft(()=>confirm('Sign out?',`The saved account session will be removed. Local reading snapshots remain on this phone. Widgets will ask you to sign in.`,()=>{s.signed=false;s.device=null;s.screen='signin';s.notice='Signed out.';M.resetDraft(s);render();},'Sign out'));return;}});
document.addEventListener('submit',e=>{if(e.target.id!=='login-form')return;e.preventDefault();if(!$('#identity').value.trim()||!$('#password').value){s.notice='Enter your mobile number or email and password.';s.severity='error';render();return;}request('login');});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();close();return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet a')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#modal-root').addEventListener('click',e=>{if(e.target===$('#modal-root'))close();});
function download(kind){let csv=kind==='energy'?'date,energy_kwh,note\n2026-10-19,1.26,partial sample\n2026-10-18,3.48,sample\n':'timestamp,device,room_c,target_c,mode,fan_setting\n2026-10-19T10:24:00,Bedroom,24.18,23,cool,auto\n';let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='openmiraie-'+kind+'-sample.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);close();s.notice='Sample CSV download requested. Native app confirms after the file is written.';render();}
if(location.hash.slice(1) in notes)journey(location.hash.slice(1));else render();
